UPDATE course_lessons SET content = REPLACE(
  REPLACE(
    REPLACE(content,
      '| C to S | Highest resistance |',
      '| S to R | Highest resistance (equals C-S + C-R) |'
    ),
    '| C to R | Middle resistance |',
    '| C to S | Middle resistance (start winding has more turns) |'
  ),
  '| S to R | C-S + C-R (should equal sum) |',
  '| C to R | Lowest resistance (run winding has fewer turns, thicker wire) |'
) WHERE id = 60024;

